// 週次のやり残しレポート。
// 宣言的モデルでは「あるべき状態と実態の差」がそのままやり残しなので、
// リコンサイラをドライランで走らせてその差を取得する
// (同じ計算を二重に実装しないため)。
// 設計: docs/design/01-member-lifecycle.md#バックストップ監査
return [{ json: { dryRun: true } }];

// レポートを組み立てる。
// 個別のリマインドが握りつぶされても、ここで必ず全体像が浮上するようにする。

const dry = $('未収束を調べる').first()?.json ?? {};
const members = $('メンバーを読む').all().map((i) => i.json).filter((m) => m.desired);
const pcs = $input.all().map((i) => i.json).filter((p) => p.state);

const now = new Date();
const days = (a, b) => Math.floor((a - b) / 86400000);
const L = [];
let issues = 0;

const section = (title, lines, note) => {
  if (!lines.length) return;
  issues += lines.length;
  L.push(`■ ${title}(${lines.length} 件)`);
  if (note) L.push(`  ${note}`);
  lines.forEach((x) => L.push(`  - ${x}`));
  L.push('');
};

// 1. 未収束(あるべき状態に追いついていない)
section('未収束の付与・剥奪', dry.pending ?? [],
  'リコンサイラが適用を試み続けています。何日も残る場合は失敗が続いています。');
section('未実装のコネクタでスキップ', dry.skipped ?? [],
  '自動化されていないため、当面は手動対応が必要です。');

// 2. タスクの滞留
const overdue = [];
const escalated = [];
const longOpen = [];
const collect = (rec, label) => {
  for (const t of (rec.state?.tasks ?? [])) {
    if (t.status === 'escalated') { escalated.push(`${label}: ${t.subject}(担当 ${t.assignee})`); continue; }
    if (t.status !== 'open') continue;
    if (t.due && days(now, new Date(t.due)) > 0) {
      overdue.push(`${label}: ${t.subject}(期限 ${t.due} / ${days(now, new Date(t.due))} 日超過 / 担当 ${t.assignee})`);
    } else if (t.created_at && days(now, new Date(t.created_at)) >= 30) {
      longOpen.push(`${label}: ${t.subject}(${days(now, new Date(t.created_at))} 日経過)`);
    }
  }
};
for (const m of members) collect(m, `${m.desired.name ?? m.id}`);
for (const p of pcs) collect(p, `${p.state.computer_name?.value ?? p.id}`);

section('エスカレーション済み(担当者が対応できていない)', escalated,
  '管理者の介入が必要です。');
section('期限超過のタスク', overdue);
section('30日以上未完了のタスク', longOpen);

// 3. 適用の失敗
const failures = [];
for (const m of members) {
  for (const [svc, msg] of Object.entries(m.state?.failures ?? {})) {
    failures.push(`${m.desired.name ?? m.id} / ${svc}: ${msg}`);
  }
}
section('適用に失敗したまま残っているもの', failures,
  '再試行は続きますが、権限不足など設定の問題なら人手の対応が要ります。');

// 4. PC の滞留
const provisional = pcs.filter((p) => p.state.computer_name?.provisional || p.state.asset_no?.provisional)
  .map((p) => `${p.state.computer_name?.value ?? p.id}(資産番号 ${p.state.asset_no?.value ?? p.id})`);
section('仮の資産管理番号・コンピュータ名のままの PC', provisional,
  '情シスの正式採番を反映してください。');

const noIp = pcs.filter((p) => !p.state.ip_address)
  .map((p) => `${p.state.computer_name?.value ?? p.id}`);
section('IP アドレスが未登録の PC', noIp,
  '必須ではありませんが、記録のため登録してください。');

const stuck = pcs.filter((p) => p.state.status && p.state.status !== 'active' && p.state.status !== 'retired')
  .map((p) => `${p.state.computer_name?.value ?? p.id}(${p.state.status})`);
section('利用開始の手続きが完了していない PC', stuck);

// 5. 協力会社メンバーの契約期限
const contracts = members.filter((m) => m.desired.status === 'active' && m.desired.contract_until)
  .map((m) => ({ m, left: -days(now, new Date(m.desired.contract_until)) }))
  .filter((x) => x.left <= 60)
  .map((x) => `${x.m.desired.name ?? x.m.id}: ${x.m.desired.contract_until}`
    + (x.left < 0 ? `(${-x.left} 日超過)` : `(残り ${x.left} 日)`)
    + ` / 受入責任者 ${x.m.desired.sponsor}`);
section('契約期限が近い・過ぎている協力会社メンバー', contracts,
  '期限を過ぎてもアクセスは自動停止しません。継続か終了かの PR を出してください。');

const header = issues === 0
  ? ['週次監査: やり残しはありません。', '',
     `メンバー ${members.length} 名 / PC ${pcs.length} 台 — すべて収束しています。`]
  : [`週次監査: ${issues} 件の未処理があります。`, ''];

const body = [...header, ...L,
  '───────────────',
  `対象: メンバー ${members.length} 名 / PC ${pcs.length} 台`,
  `実行: ${now.toISOString()}`,
].join('\n');

return [{ json: {
  to: String($env.ADMIN_EMAILS ?? '').split(',').map((s) => s.trim()).filter(Boolean),
  level: issues > 0 ? 'warn' : 'info',
  subject: issues === 0 ? '週次監査: やり残しなし' : `週次監査: ${issues} 件の未処理`,
  body,
  __issues: issues,
}}];
